using System.Net;
using System.Security.Cryptography;
using System.Diagnostics;
namespace PurpleStream;
static class AppTests {
 sealed class Bytes(byte[] bytes,bool html=false):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken){var response=new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)};response.Content.Headers.ContentType=new(html?"text/html":"video/mp4");return Task.FromResult(response);}}
 static void Check(bool valid,string message){if(!valid)throw new Exception(message);}
 static async Task Wait(Func<bool> predicate,string message,int ms=20000){var end=DateTime.UtcNow.AddMilliseconds(ms);while(!predicate()){if(DateTime.UtcNow>end)throw new Exception(message);await Task.Delay(120);}}
 public static async Task Run(){WindowsFormsSynchronizationContext.AutoInstall=false;var report=new List<string>();string work=Path.GetFullPath("work/v4-tests");Directory.CreateDirectory(work);string result=Path.Combine(AppContext.BaseDirectory,"tests.txt");try{
 DirectoryTests.Run();await NetworkTests.Run();report.Add("PASS: existing country, metadata, manual override, timeout and redaction regression tests.");
 var saved=new Saved{Mode="Xtream Codes",Server="http://fixture.invalid",User="test",Secret=SettingsStore.Protect("fixture")};using(var service=new ProviderService(saved,new ProviderTransport(new OfflineFixture()))){await service.Authenticate(default);var live=await service.Catalog("Live TV",default);var movies=await service.Catalog("Movies",default);var series=await service.Catalog("Series",default);Check(CatalogDirectory.Locate(movies.Single(),saved.Organization).Country.Code=="IN","Movie country grouping");Check(CatalogDirectory.Locate(movies.Single(),saved.Organization).Genre=="Action","Movie genre grouping");Check(CatalogDirectory.Locate(series.Single(),saved.Organization).Country.Code=="TR","Series country grouping");var episodes=await service.Episodes(series.Single(),default);Check(episodes.Single().Kind=="Episode"&&episodes.Single().Season=="1","Episode structure");var guide=await service.Guide(live.Single(),default);Check(guide.Single().Title=="Fixture programme","EPG decode");var archive=service.Catchup(live.Single(),guide.Single());Check(archive.Kind=="Catch-up"&&archive.Url.Contains("/timeshift/test/fixture/60/"),"Catch-up construction");report.Add("PASS: Xtream login, Live/Movie/Series category names, movie/series countries and genres, seasons/episodes, EPG and archive URL.");}
 string xml="<tv><channel id='fixture'><display-name>Test</display-name></channel><programme channel='fixture' start='20261021120000 +0500' stop='20261021130000 +0500'><title>XMLTV test</title><desc>Details</desc></programme></tv>";var entries=ProviderService.ParseXmlGuide(xml,new("Test","https://fixture.invalid","Other",EpgId:"fixture"));Check(entries.Single().Start.UtcDateTime.Hour==7,"XMLTV timezone");bool rejected=false;try{ProviderService.ParseXmlGuide("<!DOCTYPE tv SYSTEM 'file:///secret'><tv/>",new("Test","https://fixture.invalid","Other"));}catch(System.Xml.XmlException){rejected=true;}Check(rejected,"XMLTV unsafe DTD");report.Add("PASS: XMLTV channel mapping, timezone and external-entity rejection.");
 var data=Enumerable.Range(0,500000).Select(i=>(byte)(i%251)).ToArray();using(var manager=new TransferManager(new Bytes(data))){var job=manager.Download(new("Fixture movie","https://fixture.invalid/movie.mp4","India | Action","Movies"),work);await job.Work!;Check(job.Status.State=="Completed"&&File.ReadAllBytes(job.File).SequenceEqual(data),"Download byte integrity");}using(var manager=new TransferManager(new Bytes(data,true))){var job=manager.Download(new("Denied","https://fixture.invalid/movie.mp4","Other","Movies"),work);await job.Work!;Check(job.Status.State=="Failed"&&!File.Exists(job.File),"HTML not video");}report.Add("PASS: asynchronous VOD file download byte integrity and rejection of HTML login/error pages.");
 string video=Path.GetFullPath("work/test-video.avi");Check(File.Exists(video),"Original video fixture missing");using var surface=new Form();var hwnd=surface.Handle;SynchronizationContext.SetSynchronizationContext(null);string wav=Path.Combine(work,"seek.wav");using(var writer=new BinaryWriter(File.Create(wav))){int bytes=44100*2*20;writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));writer.Write(bytes+36);writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(44100);writer.Write(88200);writer.Write((short)2);writer.Write((short)16);writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));writer.Write(bytes);writer.Write(new byte[bytes]);}using(var engine=new AsyncPlayback(hwnd)){var watch=Stopwatch.StartNew();engine.Play(new Uri(wav).AbsoluteUri,0);Check(watch.ElapsedMilliseconds<200,"Play blocked caller");await Wait(()=>engine.State.State==3,"Native playback not playing");await Wait(()=>engine.State.Seekable&&engine.State.Length>0,"VOD not seekable");engine.Seek(12000);await Wait(()=>engine.State.Time>=9000,"Seek did not advance",5000);engine.Pause();await Wait(()=>engine.State.State==4,"Pause failed",4000);engine.Pause();engine.Rate(1.25f);await engine.StopAsync().WaitAsync(TimeSpan.FromSeconds(8));}report.Add("PASS: dedicated background native player initialization/play/stop, VOD seeking, pause/resume, speed command.");
 var screens=Enumerable.Range(0,4).Select(_=>new AsyncPlayback(hwnd)).ToArray();try{foreach(var screen in screens)screen.Play(new Uri(video).AbsoluteUri,0);await Wait(()=>screens.All(s=>s.State.State==3),"Four-screen playback",30000);}finally{foreach(var screen in screens)screen.Dispose();}report.Add("PASS: four independent simultaneous native playback sessions on local fixture.");
 string capture=Path.Combine(work,"capture-"+Guid.NewGuid().ToString("N")+".ts");using(var recorder=new AsyncPlayback(IntPtr.Zero)){recorder.Play(new Uri(video).AbsoluteUri,0,output:capture,transcode:true);await Wait(()=>recorder.State.State==6||recorder.State.State==7,"Capture did not finish",40000);Check(recorder.State.State!=7,"Capture native error");await recorder.StopAsync().WaitAsync(TimeSpan.FromSeconds(10));recorder.Dispose();await recorder.Completion.WaitAsync(TimeSpan.FromSeconds(10));}Check(File.Exists(capture)&&new FileInfo(capture).Length>188,"Capture output empty");using(var decode=new AsyncPlayback(hwnd)){decode.Play(new Uri(capture).AbsoluteUri,0);await Wait(()=>decode.State.State==3,"Captured MPEG-TS not playable",12000);}report.Add("PASS: native stream capture/remux pipeline produced playable MPEG-TS from original local video.");
 using(var manager=new TransferManager()){var recording=manager.Capture(new("Production recording",new Uri(capture).AbsoluteUri,"Test"),work,true);await recording.Work!.WaitAsync(TimeSpan.FromSeconds(30));Check(recording.Status.State=="Completed"&&File.Exists(recording.File)&&new FileInfo(recording.File).Length>188,"Production recording finalization");}report.Add("PASS: production recording job remuxes MPEG-TS, closes native output and atomically finalizes a nonempty file.");
 var serial=Playlist.Parse("#EXTM3U\n#EXTINF:-1 group-title=\"Pakistan Series\",Example S01E02\nhttps://fixture.invalid/series/test/episode.mp4");Check(serial.Single().Kind=="Episode"&&serial.Single().SeriesTitle=="Example"&&serial.Single().Season=="01","M3U episode metadata");report.Add("PASS: M3U episode/season naming and series grouping metadata.");
 var rapid=new AsyncPlayback(hwnd);var elapsed=Stopwatch.StartNew();rapid.Play("http://192.0.2.1:9/unavailable",0);rapid.Seek(10000);rapid.Stop();rapid.Dispose();Check(elapsed.ElapsedMilliseconds<200,"Unavailable stream blocked UI-facing commands");report.Add("PASS: connection/play/seek/stop/dispose commands return promptly even for unavailable stream.");
 report.Add("LIMITS: tests use in-memory provider responses and local original media. Actual provider, internet downloads, provider archives and recording quotas require real-account testing. Native thumbnail warnings may appear in the restricted test desktop.");File.WriteAllLines(result,report);
 }catch(Exception e){report.Add("FAIL: "+e);File.WriteAllLines(result,report);throw;}}
}

